import numpy as np
A=np.array([[1,6,7,3,6],[1,7,1,1,6],[1,1,6,1,3],[3,6,1,6,1],[7,1,1,1,1]])
B=np.array([[1,6,7,3,6,7,3,1,1,1],[1,7,1,1,6,1,6,1,7,6],[1,1,6,1,3,1,1,6,1,7],[3,6,1,6,1,1,6,1,1,3],[7,1,1,1,1,1,1,3,6,6],[6,6,3,1,1,1,1,1,1,7],[3,1,1,6,1,1,6,1,6,3],[7,1,6,1,1,3,1,6,1,1],[6,7,1,6,1,6,1,1,7,1],[1,1,1,3,7,6,3,7,6,1]])
blocks=[B[:5,:5],B[:5,5:],B[5:,:5],B[5:,5:]]
syms=[]
for k in range(4):
 for flip in [False,True]:
  X=np.rot90(A,k)
  if flip: X=np.fliplr(X)
  syms.append(X)
for i,Q in enumerate(blocks): print(i,[j for j,X in enumerate(syms) if np.array_equal(X,Q)])
# check row/col permutations existence: multisets of rows after arbitrary column permutation etc
for i,Q in enumerate(blocks[1:],1):
 print('block',i)
 print(Q)
